14	/// An iterator over a source code string which returns tokens.
15	#[derive(Clone)]
16	pub(super) struct Lexer<'s> {
17	    /// The scanner: contains the underlying string and location as a "cursor".
18	    s: Scanner<'s>,
19	    /// The mode the lexer is in. This determines which kinds of tokens it
20	    /// produces.
21	    mode: SyntaxMode,
22	    /// Whether the last token contained a newline.
23	    newline: bool,
24	    /// An error plus hints for the current token being produced. This is always
25	    /// `None` between calls to [`Lexer::next`].
26	    error: Option<(EcoString, EcoVec<EcoString>)>,
27	}
28	
29	impl<'s> Lexer<'s> {
30	    /// Create a new lexer with the given mode and a prefix to offset column
31	    /// calculations.
32	    pub fn new(text: &'s str, mode: SyntaxMode) -> Self {
33	        Self {
34	            s: Scanner::new(text),
35	            mode,
36	            newline: false,
37	            error: None,
38	        }
39	    }
40	
41	    /// Get the current lexing mode.
42	    pub fn mode(&self) -> SyntaxMode {
43	        self.mode
44	    }
45	
46	    /// Change the lexing mode.
47	    pub fn set_mode(&mut self, mode: SyntaxMode) {
48	        self.mode = mode;
49	    }
50	
51	    /// The index in the string at which the last token ends and next token
52	    /// will start.
53	    pub fn cursor(&self) -> usize {
54	        self.s.cursor()
55	    }
56	
57	    /// Jump to the given index in the string.
58	    pub fn jump(&mut self, index: usize) {
59	        self.s.jump(index);
60	    }
61	
62	    /// Whether the last token contained a newline.
63	    pub fn newline(&self) -> bool {
64	        self.newline
65	    }
66	
67	    /// The number of characters until the most recent newline from an index.
68	    pub fn column(&self, index: usize) -> usize {
69	        let mut s = self.s; // Make a new temporary scanner (cheap).
70	        s.jump(index);
71	        s.before().chars().rev().take_while(|&c| !is_newline(c)).count()
72	    }
73	}
