75	impl Lexer<'_> {
76	    /// Construct a full-positioned syntax error.
77	    fn error(&mut self, message: impl Into<EcoString>) -> SyntaxKind {
78	        debug_assert!(self.error.is_none());
79	        self.error = Some((message.into(), eco_vec![]));
80	        SyntaxKind::Error
81	    }
82	
83	    /// If the current node is an error, adds a hint.
84	    fn hint(&mut self, message: impl Into<EcoString>) {
85	        if let Some((_message, hints)) = &mut self.error {
86	            hints.push(message.into());
87	        }
88	    }
89	}
90	
91	/// Shared methods with all [`SyntaxMode`].
92	impl Lexer<'_> {
93	    /// Return the next token in our text. Returns both the [`SyntaxNode`]
94	    /// and the raw [`SyntaxKind`] to make it more ergonomic to check the kind
95	    pub fn next(&mut self) -> (SyntaxKind, SyntaxNode) {
96	        debug_assert!(self.error.is_none());
97	        let start = self.s.cursor();
98	
99	        self.newline = false;
100	        let kind = match self.s.eat() {
101	            Some(c) if is_space(c, self.mode) => self.whitespace(start, c),
102	            Some('#') if start == 0 && self.s.eat_if('!') => self.shebang(),
103	            Some('/') if self.s.eat_if('/') => self.line_comment(),
104	            Some('/') if self.s.eat_if('*') => self.block_comment(),
105	            Some('*') if self.s.eat_if('/') => {
106	                let error = self.error("unexpected end of block comment");
107	                self.hint(
108	                    "consider escaping the `*` with a backslash or \
109	                     opening the block comment with `/*`",
110	                );
111	                error
112	            }
113	            Some('`') if self.mode != SyntaxMode::Math => return self.raw(),
114	            Some(c) => match self.mode {
115	                SyntaxMode::Markup => self.markup(start, c),
116	                SyntaxMode::Math => match self.math(start, c) {
117	                    (kind, None) => kind,
118	                    (kind, Some(node)) => return (kind, node),
119	                },
120	                SyntaxMode::Code => self.code(start, c),
121	            },
122	
123	            None => SyntaxKind::End,
124	        };
125	
126	        let text = self.s.from(start);
127	        let node = match self.error.take() {
128	            Some((message, hints)) => SyntaxNode::error(message, text).with_hints(hints),
129	            None => SyntaxNode::leaf(kind, text),
130	        };
131	        (kind, node)
132	    }
133	
134	    /// Eat whitespace characters greedily.
135	    fn whitespace(&mut self, start: usize, c: char) -> SyntaxKind {
136	        let more = self.s.eat_while(|c| is_space(c, self.mode));
137	        let newlines = match c {
138	            // Optimize eating a single space.
139	            ' ' if more.is_empty() => 0,
140	            _ => count_newlines(self.s.from(start)),
141	        };
142	
143	        self.newline = newlines > 0;
144	        if self.mode == SyntaxMode::Markup && newlines >= 2 {
145	            SyntaxKind::Parbreak
146	        } else {
147	            SyntaxKind::Space
148	        }
149	    }
150	
151	    fn shebang(&mut self) -> SyntaxKind {
152	        self.s.eat_until(is_newline);
153	        SyntaxKind::Shebang
154	    }
155	
156	    fn line_comment(&mut self) -> SyntaxKind {
157	        self.s.eat_until(is_newline);
158	        SyntaxKind::LineComment
159	    }
160	
161	    fn block_comment(&mut self) -> SyntaxKind {
162	        let mut state = '_';
163	        let mut depth = 1;
164	
165	        // Find the first `*/` that does not correspond to a nested `/*`.
166	        while let Some(c) = self.s.eat() {
167	            state = match (state, c) {
168	                ('*', '/') => {
169	                    depth -= 1;
170	                    if depth == 0 {
171	                        break;
172	                    }
173	                    '_'
174	                }
175	                ('/', '*') => {
176	                    depth += 1;
177	                    '_'
178	                }
179	                _ => c,
180	            }
181	        }
182	
183	        SyntaxKind::BlockComment
184	    }
185	}
