187	/// Raw.
188	impl Lexer<'_> {
189	    /// We parse entire raw segments in the lexer as a convenience to avoid
190	    /// going to and from the parser for each raw section.
191	    fn raw(&mut self) -> (SyntaxKind, SyntaxNode) {
192	        let start = self.s.cursor() - 1;
193	
194	        // Determine number of opening backticks.
195	        let mut backticks = 1;
196	        while self.s.eat_if('`') {
197	            backticks += 1;
198	        }
199	
200	        // Special case for ``.
201	        if backticks == 2 {
202	            let nodes = vec![
203	                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
204	                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
205	            ];
206	            return (SyntaxKind::Raw, SyntaxNode::inner(SyntaxKind::Raw, nodes));
207	        }
208	
209	        // Find end of raw text.
210	        let mut found = 0;
211	        while found < backticks {
212	            match self.s.eat() {
213	                Some('`') => found += 1,
214	                Some(_) => found = 0,
215	                None => {
216	                    let message = "unclosed raw text";
217	                    let error = SyntaxNode::error(message, self.s.from(start));
218	                    return (SyntaxKind::Error, error);
219	                }
220	            }
221	        }
222	        let end = self.s.cursor();
223	
224	        let mut inner = Scanner::new(self.s.get(start + backticks..end - backticks));
225	        let inner_len = inner.string().len();
226	
227	        // Opening delimiter.
228	        let delim = SyntaxNode::leaf(SyntaxKind::RawDelim, self.s.from(end - backticks));
229	        let mut nodes = vec![delim.clone()];
230	
231	        let mut tag = None;
232	        let mut diff_future_tag_len = None;
233	        if delim.len() >= 3 {
234	            (tag, diff_future_tag_len) = Self::raw_lang_tag(&mut inner);
235	            if let Some(tag) = tag {
236	                nodes.push(SyntaxNode::leaf(SyntaxKind::RawLang, tag));
237	            }
238	            Self::blocky_raw(&mut inner, &mut nodes);
239	        } else {
240	            Self::inline_raw(&mut inner, &mut nodes);
241	        }
242	
243	        // Closing delimiter.
244	        nodes.push(delim);
245	
246	        let mut raw = SyntaxNode::inner(SyntaxKind::Raw, nodes);
247	
248	        Self::add_raw_warnings(&mut raw, backticks, diff_future_tag_len, tag, inner_len);
249	
250	        (SyntaxKind::Raw, raw)
251	    }
252	
253	    /// Lex the raw language tag into an optional string and return the length
254	    /// of the future language tag if it will differ in the next version.
255	    ///
256	    /// See [`Self::add_raw_warnings`] for more.
257	    fn raw_lang_tag<'a>(s: &mut Scanner<'a>) -> (Option<&'a str>, Option<usize>) {
258	        let start = s.cursor();
259	        let future_tag = s.eat_until(|c: char| c.is_whitespace() || c == '`');
260	        if future_tag.is_empty() {
261	            // Future tag is always longer than current tag, if empty, we have
262	            // no current tag either.
263	            return (None, None);
264	        }
265	        s.jump(start);
266	        let tag = s.eat_if(is_id_start).then(|| {
267	            s.eat_while(is_id_continue);
268	            s.from(start)
269	        });
270	        let diff_future_tag_len = tag
271	            .is_none_or(|tag| tag.len() != future_tag.len())
272	            .then_some(future_tag.len());
273	        (tag, diff_future_tag_len)
274	    }
275	
276	    /// Raw blocks parse a language tag, have smart behavior for trimming
277	    /// whitespace in the start/end lines, and trim common leading whitespace
278	    /// from all other lines as the "dedent". The exact behavior is described
279	    /// below.
280	    ///
281	    /// ### The initial line:
282	    /// - The language tag is already handled above.
283	    /// - We check the rest of the line and if all characters are whitespace,
284	    ///   trim it. Otherwise we trim a single leading space if present.
285	    ///   - If more trimmed characters follow on future lines, they will be
286	    ///     merged into the same trimmed element.
287	    /// - If we didn't trim the entire line, the rest is kept as text.
288	    ///
289	    /// ### Inner lines:
290	    /// - We determine the "dedent" by iterating over the lines. The dedent is
291	    ///   the minimum number of leading whitespace characters (not bytes) before
292	    ///   each line that has any non-whitespace characters.
293	    ///   - The opening delimiter's line does not contribute to the dedent, but
294	    ///     the closing delimiter's line does (even if that line is entirely
295	    ///     whitespace up to the delimiter).
296	    /// - We then trim the newline and dedent characters of each line, and add a
297	    ///   (potentially empty) text element of all remaining characters.
298	    ///
299	    /// ### The final line:
300	    /// - If the last line is entirely whitespace, it is trimmed.
301	    /// - Otherwise its text is kept like an inner line. However, if the last
302	    ///   non-whitespace character of the final line is a backtick, then one
303	    ///   ascii space (if present) is trimmed from the end.
304	    fn blocky_raw(s: &mut Scanner, nodes: &mut Vec<SyntaxNode>) {
305	        // The lines between the backticks.
306	        let mut lines = split_newlines(s.after());
307	
308	        // Determine dedent level.
309	        let dedent = lines
310	            .iter()
311	            .skip(1)
312	            .filter(|line| !line.chars().all(char::is_whitespace))
313	            // The line with the closing ``` is always taken into account
314	            .chain(lines.last())
315	            .map(|line| line.chars().take_while(|c| c.is_whitespace()).count())
316	            .min()
317	            .unwrap_or(0);
318	
319	        // Trim whitespace from the last line. Will be added as a `RawTrimmed`
320	        // kind by the check for `self.s.cursor() != inner_end` below.
321	        if lines.last().is_some_and(|last| last.chars().all(char::is_whitespace)) {
322	            lines.pop();
323	        } else if let Some(last) = lines.last_mut() {
324	            // If last line ends in a backtick, try to trim a single space. This
325	            // check must happen before we add the first line since the last and
326	            // first lines might be the same.
327	            if last.trim_end().ends_with('`') {
328	                *last = last.strip_suffix(' ').unwrap_or(last);
329	            }
330	        }
331	
332	        // A closure for pushing a leaf node and updating the cursor in one
333	        // step.
334	        let mut prev = s.cursor();
335	        let mut push_leaf = |kind, s: &Scanner| {
336	            nodes.push(SyntaxNode::leaf(kind, s.from(prev)));
337	            prev = s.cursor();
338	        };
339	
340	        let mut lines = lines.into_iter();
341	
342	        // Handle the first line: trim if all whitespace, or trim a single space
343	        // at the start. Note that the first line does not affect the dedent
344	        // value.
345	        if let Some(first_line) = lines.next() {
346	            if first_line.chars().all(char::is_whitespace) {
347	                s.advance(first_line.len());
348	                // This is the only spot we advance the scanner, but don't
349	                // immediately call `push_leaf`. But the rest of the function
350	                // ensures we will always add this text to a `RawTrimmed` later.
351	                debug_assert!(!s.done());
352	                // A proof by cases follows:
353	                // # First case: The loop runs
354	                // If the loop runs, there must be a newline following, so
355	                // `cursor != inner_end`. And if the loop runs, the first thing
356	                // it does is add a trimmed element.
357	                // # Second case: The final if-statement runs.
358	                // To _not_ reach the loop from here, we must have only one or
359	                // two lines:
360	                // 1. If one line, we cannot be here, because the first and last
361	                //    lines are the same, so this line will have been removed by
362	                //    the check for the last line being all whitespace.
363	                // 2. If two lines, the loop will run unless the last is fully
364	                //    whitespace, but if it is, it will have been popped, then
365	                //    the final if-statement will run because the text removed
366	                //    by the last line must include at least a newline, so
367	                //    `cursor != inner_end` here.
368	            } else {
369	                let line_end = s.cursor() + first_line.len();
370	                if s.eat_if(' ') {
371	                    // Trim a single space after the lang tag or backticks on
372	                    // the first line.
373	                    push_leaf(SyntaxKind::RawTrimmed, s);
374	                }
375	                // We know here that the rest of the line is non-empty.
376	                s.jump(line_end);
377	                push_leaf(SyntaxKind::Text, s);
378	            }
379	        }
380	
381	        // Add lines.
382	        for line in lines {
383	            let offset: usize = line.chars().take(dedent).map(char::len_utf8).sum();
384	            s.eat_newline();
385	            s.advance(offset);
386	            push_leaf(SyntaxKind::RawTrimmed, s);
387	            s.advance(line.len() - offset);
388	            push_leaf(SyntaxKind::Text, s);
389	        }
390	
391	        // Add final trimmed.
392	        if !s.done() {
393	            nodes.push(SyntaxNode::leaf(SyntaxKind::RawTrimmed, s.after()));
394	        }
395	    }
396	
397	    /// Inline raw text is split on lines with non-newlines as `Text` kinds and
398	    /// newlines as `RawTrimmed`. Inline raw text does not dedent the text, all
399	    /// non-newline whitespace is kept.
400	    fn inline_raw(s: &mut Scanner, nodes: &mut Vec<SyntaxNode>) {
401	        let mut prev = s.cursor();
402	        while !s.done() {
403	            if s.at(is_newline) {
404	                nodes.push(SyntaxNode::leaf(SyntaxKind::Text, s.from(prev)));
405	                prev = s.cursor();
406	                s.eat_newline();
407	                nodes.push(SyntaxNode::leaf(SyntaxKind::RawTrimmed, s.from(prev)));
408	                prev = s.cursor();
409	                continue;
410	            }
411	            s.eat();
412	        }
413	        nodes.push(SyntaxNode::leaf(SyntaxKind::Text, s.from(prev)));
414	    }
415	
416	    /// Add warnings if the raw language tag will differ in the next version of
417	    /// Typst or if there is a language tag but the raw text is empty.
418	    ///
419	    /// Currently, we parse the language tag only up to the end of a valid
420	    /// identifier or the first whitespace. So if we start with `C++`, the
421	    /// identifier `C` will be the language tag, and the raw text will start
422	    /// with `++`. If we start with `++C`, we will have no language tag and the
423	    /// raw text will start with `++C`.
424	    ///
425	    /// In the next version of Typst, we will parse all text up to the first
426	    /// whitespace or backtick, so tags like `C++` or `html.j2` or `$!#%@` can
427	    /// be written without issue
428	    ///
429	    /// However, this may cause some documents relying on the behavior of raw
430	    /// text starting like `C++` or `++C` to change, so we are giving a warning
431	    /// for those cases.
432	    fn add_raw_warnings(
433	        raw: &mut SyntaxNode,
434	        backticks: usize,
435	        diff_future_tag_len: Option<usize>,
436	        tag: Option<&str>,
437	        inner_len: usize,
438	    ) {
439	        // Add a warning if the tag will differ in the next version.
440	        if let Some(future_tag_len) = diff_future_tag_len {
441	            let future_range = backticks..backticks + future_tag_len;
442	            if let Some(tag) = tag {
443	                raw.warn_at(
444	                    future_range,
445	                    "no whitespace between language tag and raw text",
446	                );
447	                raw.hint(eco_format!(
448	                    "currently, Typst is treating `{tag}` as the language tag"
449	                ));
450	                raw.hint(
451	                    "in the next version of Typst, this will change and we will treat \
452	                        all text until the first whitespace as the language tag",
453	                );
454	                let tag_range = backticks..backticks + tag.len();
455	                raw.hint_at(tag_range.clone(), eco_format!(
456	                    "if the current behavior is correct, please add a space after `{tag}`"
457	                ));
458	                raw.hint_at(
459	                    tag_range,
460	                    "otherwise, add a space or newline after the initial backticks",
461	                );
462	            } else {
463	                raw.warn_at(future_range, "no whitespace before raw text");
464	                raw.hint(
465	                    "in the next version of Typst, this text will be treated as \
466	                        the language tag for this element",
467	                );
468	                raw.hint("to avoid this, add a space after the initial backticks");
469	            }
470	        } else if let Some(tag) = tag
471	            && inner_len == tag.len()
472	        {
473	            // Empty with no tag/ws is only possible with exactly two backticks,
474	            // which is handled by the caller.
475	            raw.warn("empty raw text");
476	            raw.hint(eco_format!("Typst is treating `{tag}` as the language tag"));
477	            let tag_range = backticks..backticks + tag.len();
478	            raw.hint_at(
479	                tag_range,
480	                "to treat this as text, add a space after the initial backticks",
481	            );
482	        }
483	    }
484	}
