486	/// Markup.
487	impl Lexer<'_> {
488	    fn markup(&mut self, start: usize, c: char) -> SyntaxKind {
489	        match c {
490	            '\\' => self.backslash(),
491	            'h' if self.s.eat_if("ttp://") => self.link(),
492	            'h' if self.s.eat_if("ttps://") => self.link(),
493	            '<' if self.s.at(is_id_continue) => self.label(),
494	            '@' if self.s.at(is_id_continue) => self.ref_marker(),
495	
496	            '.' if self.s.eat_if("..") => SyntaxKind::Shorthand,
497	            '-' if self.s.eat_if("--") => SyntaxKind::Shorthand,
498	            '-' if self.s.eat_if('-') => SyntaxKind::Shorthand,
499	            '-' if self.s.eat_if('?') => SyntaxKind::Shorthand,
500	            '-' if self.s.at(char::is_numeric) => SyntaxKind::Shorthand,
501	            '*' if !self.in_word() => SyntaxKind::Star,
502	            '_' if !self.in_word() => SyntaxKind::Underscore,
503	
504	            '#' => SyntaxKind::Hash,
505	            '[' => SyntaxKind::LeftBracket,
506	            ']' => SyntaxKind::RightBracket,
507	            '\'' => SyntaxKind::SmartQuote,
508	            '"' => SyntaxKind::SmartQuote,
509	            '$' => SyntaxKind::Dollar,
510	            '~' => SyntaxKind::Shorthand,
511	            ':' => SyntaxKind::Colon,
512	            '=' => {
513	                self.s.eat_while('=');
514	                if self.space_or_end() { SyntaxKind::HeadingMarker } else { self.text() }
515	            }
516	            '-' if self.space_or_end() => SyntaxKind::ListMarker,
517	            '+' if self.space_or_end() => SyntaxKind::EnumMarker,
518	            '/' if self.space_or_end() => SyntaxKind::TermMarker,
519	            '0'..='9' => self.numbering(start),
520	
521	            _ => self.text(),
522	        }
523	    }
524	
525	    fn backslash(&mut self) -> SyntaxKind {
526	        if self.s.eat_if("u{") {
527	            let hex = self.s.eat_while(char::is_ascii_alphanumeric);
528	            if !self.s.eat_if('}') {
529	                return self.error("unclosed Unicode escape sequence");
530	            }
531	
532	            if u32::from_str_radix(hex, 16)
533	                .ok()
534	                .and_then(std::char::from_u32)
535	                .is_none()
536	            {
537	                return self.error(eco_format!("invalid Unicode codepoint: {hex}"));
538	            }
539	
540	            return SyntaxKind::Escape;
541	        }
542	
543	        if self.s.done() || self.s.at(char::is_whitespace) {
544	            SyntaxKind::Linebreak
545	        } else {
546	            self.s.eat();
547	            SyntaxKind::Escape
548	        }
549	    }
550	
551	    fn link(&mut self) -> SyntaxKind {
552	        let (link, balanced) = link_prefix(self.s.after());
553	        self.s.advance(link.len());
554	
555	        if !balanced {
556	            return self.error(
557	                "automatic links cannot contain unbalanced brackets, \
558	                 use the `link` function instead",
559	            );
560	        }
561	
562	        SyntaxKind::Link
563	    }
564	
565	    fn numbering(&mut self, start: usize) -> SyntaxKind {
566	        self.s.eat_while(char::is_ascii_digit);
567	
568	        let read = self.s.from(start);
569	        if self.s.eat_if('.') && self.space_or_end() && read.parse::<u64>().is_ok() {
570	            return SyntaxKind::EnumMarker;
571	        }
572	
573	        self.text()
574	    }
575	
576	    fn ref_marker(&mut self) -> SyntaxKind {
577	        self.s.eat_while(is_valid_in_label_literal);
578	
579	        // Don't include the trailing characters likely to be part of text.
580	        while matches!(self.s.scout(-1), Some('.' | ':')) {
581	            self.s.uneat();
582	        }
583	
584	        SyntaxKind::RefMarker
585	    }
586	
587	    fn label(&mut self) -> SyntaxKind {
588	        let label = self.s.eat_while(is_valid_in_label_literal);
589	        if label.is_empty() {
590	            return self.error("label cannot be empty");
591	        }
592	
593	        if !self.s.eat_if('>') {
594	            return self.error("unclosed label");
595	        }
596	
597	        SyntaxKind::Label
598	    }
599	
600	    fn text(&mut self) -> SyntaxKind {
601	        macro_rules! table {
602	            ($(|$c:literal)*) => {
603	                static TABLE: [bool; 128] = {
604	                    let mut t = [false; 128];
605	                    $(t[$c as usize] = true;)*
606	                    t
607	                };
608	            };
609	        }
610	
611	        table! {
612	            | ' ' | '\t' | '\n' | '\x0b' | '\x0c' | '\r' | '\\' | '/'
613	            | '[' | ']' | '~' | '-' | '.' | '\'' | '"' | '*' | '_'
614	            | ':' | 'h' | '`' | '$' | '<' | '>' | '@' | '#'
615	        };
616	
617	        loop {
618	            self.s.eat_until(|c: char| {
619	                TABLE.get(c as usize).copied().unwrap_or_else(|| c.is_whitespace())
620	            });
621	
622	            // Continue with the same text node if the thing would become text
623	            // anyway.
624	            let mut s = self.s;
625	            match s.eat() {
626	                Some(' ') if s.at(char::is_alphanumeric) => {}
627	                Some('/') if !s.at(['/', '*']) => {}
628	                Some('-') if !s.at(['-', '?']) => {}
629	                Some('.') if !s.at("..") => {}
630	                Some('h') if !s.at("ttp://") && !s.at("ttps://") => {}
631	                Some('@') if !s.at(is_valid_in_label_literal) => {}
632	                _ => break,
633	            }
634	
635	            self.s = s;
636	        }
637	
638	        SyntaxKind::Text
639	    }
640	
641	    fn in_word(&self) -> bool {
642	        let wordy = |c: Option<char>| {
643	            c.is_some_and(|c| {
644	                c.is_alphanumeric()
645	                    && !matches!(
646	                        c.script(),
647	                        Script::Han
648	                            | Script::Hiragana
649	                            | Script::Katakana
650	                            | Script::Hangul
651	                    )
652	            })
653	        };
654	        let prev = self.s.scout(-2);
655	        let next = self.s.peek();
656	        wordy(prev) && wordy(next)
657	    }
658	
659	    fn space_or_end(&self) -> bool {
660	        self.s.done()
661	            || self.s.at(char::is_whitespace)
662	            || self.s.at("//")
663	            || self.s.at("/*")
664	    }
665	}
