667	/// Math.
668	impl Lexer<'_> {
669	    fn math(&mut self, start: usize, c: char) -> (SyntaxKind, Option<SyntaxNode>) {
670	        let kind = match c {
671	            '\\' => self.backslash(),
672	            '"' => self.string(),
673	
674	            '-' if self.s.eat_if(">>") => SyntaxKind::MathShorthand,
675	            '-' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
676	            '-' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
677	            ':' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
678	            ':' if self.s.eat_if(":=") => SyntaxKind::MathShorthand,
679	            '!' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
680	            '.' if self.s.eat_if("..") => SyntaxKind::MathShorthand,
681	            '<' if self.s.eat_if("==>") => SyntaxKind::MathShorthand,
682	            '<' if self.s.eat_if("-->") => SyntaxKind::MathShorthand,
683	            '<' if self.s.eat_if("--") => SyntaxKind::MathShorthand,
684	            '<' if self.s.eat_if("-<") => SyntaxKind::MathShorthand,
685	            '<' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
686	            '<' if self.s.eat_if("<-") => SyntaxKind::MathShorthand,
687	            '<' if self.s.eat_if("<<") => SyntaxKind::MathShorthand,
688	            '<' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
689	            '<' if self.s.eat_if("==") => SyntaxKind::MathShorthand,
690	            '<' if self.s.eat_if("~~") => SyntaxKind::MathShorthand,
691	            '<' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
692	            '<' if self.s.eat_if('<') => SyntaxKind::MathShorthand,
693	            '<' if self.s.eat_if('-') => SyntaxKind::MathShorthand,
694	            '<' if self.s.eat_if('~') => SyntaxKind::MathShorthand,
695	            '>' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
696	            '>' if self.s.eat_if(">>") => SyntaxKind::MathShorthand,
697	            '=' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
698	            '=' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
699	            '=' if self.s.eat_if(':') => SyntaxKind::MathShorthand,
700	            '>' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
701	            '>' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
702	            '|' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
703	            '|' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
704	            '|' if self.s.eat_if('|') => SyntaxKind::MathShorthand,
705	            '~' if self.s.eat_if("~>") => SyntaxKind::MathShorthand,
706	            '~' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
707	            '*' | '-' | '~' => SyntaxKind::MathShorthand,
708	
709	            '.' => SyntaxKind::Dot,
710	            ',' => SyntaxKind::Comma,
711	            ';' => SyntaxKind::Semicolon,
712	
713	            '#' => SyntaxKind::Hash,
714	            '_' => SyntaxKind::Underscore,
715	            '$' => SyntaxKind::Dollar,
716	            '/' => SyntaxKind::Slash,
717	            '^' => SyntaxKind::Hat,
718	            '&' => SyntaxKind::MathAlignPoint,
719	            '√' | '∛' | '∜' => SyntaxKind::Root,
720	            '!' => SyntaxKind::Bang,
721	
722	            '\'' => {
723	                self.s.eat_while('\'');
724	                SyntaxKind::MathPrimes
725	            }
726	
727	            // We lex delimiters as `{Left,Right}{Brace,Paren}` and convert back
728	            // to `MathText` or `MathShorthand` in the parser.
729	            '(' => SyntaxKind::LeftParen,
730	            ')' => SyntaxKind::RightParen,
731	            // TODO: We may instead want to add `MathOpening` and `MathClosing`
732	            // kinds for these.
733	            '[' if self.s.eat_if('|') => SyntaxKind::LeftBrace,
734	            '|' if self.s.eat_if(']') => SyntaxKind::RightBrace,
735	            c if default_math_class(c) == Some(MathClass::Opening) => {
736	                SyntaxKind::LeftBrace
737	            }
738	            c if default_math_class(c) == Some(MathClass::Closing) => {
739	                SyntaxKind::RightBrace
740	            }
741	
742	            // Identifiers.
743	            c if is_math_id_start(c) && self.s.at(is_math_id_continue) => {
744	                self.s.eat_while(is_math_id_continue);
745	                let (last_index, _) =
746	                    self.s.from(start).grapheme_indices(true).next_back().unwrap();
747	                if last_index == 0 {
748	                    // If this was just a single grapheme.
749	                    SyntaxKind::MathText
750	                } else {
751	                    let (kind, node) = self.math_ident_or_field(start);
752	                    return (kind, Some(node));
753	                }
754	            }
755	
756	            // Other math atoms.
757	            _ => self.math_text(start, c),
758	        };
759	        (kind, None)
760	    }
761	
762	    /// Parse a single `MathIdent` or an entire `MathFieldAccess`.
763	    fn math_ident_or_field(&mut self, start: usize) -> (SyntaxKind, SyntaxNode) {
764	        let mut kind = SyntaxKind::MathIdent;
765	        let mut node = SyntaxNode::leaf(kind, self.s.from(start));
766	        while let Some(ident) = self.maybe_dot_ident() {
767	            kind = SyntaxKind::MathFieldAccess;
768	            let field_children = vec![
769	                node,
770	                SyntaxNode::leaf(SyntaxKind::Dot, '.'),
771	                SyntaxNode::leaf(SyntaxKind::MathIdent, ident),
772	            ];
773	            node = SyntaxNode::inner(kind, field_children);
774	        }
775	        (kind, node)
776	    }
777	
778	    /// If at a dot and a math identifier, eat and return the identifier.
779	    fn maybe_dot_ident(&mut self) -> Option<&str> {
780	        if self.s.scout(1).is_some_and(is_math_id_start) && self.s.eat_if('.') {
781	            let ident_start = self.s.cursor();
782	            self.s.eat();
783	            self.s.eat_while(is_math_id_continue);
784	            Some(self.s.from(ident_start))
785	        } else {
786	            None
787	        }
788	    }
789	
790	    fn math_text(&mut self, start: usize, c: char) -> SyntaxKind {
791	        // Keep numbers and grapheme clusters together.
792	        if c.is_numeric() {
793	            self.s.eat_while(char::is_numeric);
794	            let mut s = self.s;
795	            if s.eat_if('.') && !s.eat_while(char::is_numeric).is_empty() {
796	                self.s = s;
797	            }
798	        } else {
799	            let len = self
800	                .s
801	                .get(start..self.s.string().len())
802	                .graphemes(true)
803	                .next()
804	                .map_or(0, str::len);
805	            self.s.jump(start + len);
806	        }
807	        SyntaxKind::MathText
808	    }
809	
810	    /// Handle named arguments in math function call.
811	    pub fn maybe_math_named_arg(&mut self, start: usize) -> Option<SyntaxNode> {
812	        let cursor = self.s.cursor();
813	        self.s.jump(start);
814	        if self.s.eat_if(is_id_start) {
815	            self.s.eat_while(is_id_continue);
816	            // Check that a colon directly follows the identifier, and not the
817	            // `:=` or `::=` math shorthands.
818	            if self.s.at(':') && !self.s.at(":=") && !self.s.at("::=") {
819	                // Check that the identifier is not just `_`.
820	                let node = if self.s.from(start) != "_" {
821	                    SyntaxNode::leaf(SyntaxKind::Ident, self.s.from(start))
822	                } else {
823	                    let message = "expected identifier, found underscore";
824	                    SyntaxNode::error(message, self.s.from(start))
825	                };
826	                return Some(node);
827	            }
828	        }
829	        self.s.jump(cursor);
830	        None
831	    }
832	
833	    /// Handle spread arguments in math function call.
834	    pub fn maybe_math_spread_arg(&mut self, start: usize) -> Option<SyntaxNode> {
835	        let cursor = self.s.cursor();
836	        self.s.jump(start);
837	        if self.s.eat_if("..") {
838	            // We only infer a spread operator if it is not followed by:
839	            // - a space/trivia/end
840	            // - a dot (this would clash with the `...` math shorthand)
841	            // - an end of arg character: `,`, `;`, ')', `$` (spreads nothing)
842	            if !self.space_or_end() && !self.s.at(['.', ',', ';', ')', '$']) {
843	                let node = SyntaxNode::leaf(SyntaxKind::Dots, self.s.from(start));
844	                return Some(node);
845	            }
846	        }
847	        self.s.jump(cursor);
848	        None
849	    }
850	}
