852	/// Code.
853	impl Lexer<'_> {
854	    fn code(&mut self, start: usize, c: char) -> SyntaxKind {
855	        match c {
856	            '<' if self.s.at(is_id_continue) => self.label(),
857	            '0'..='9' => self.number(start, c),
858	            '.' if self.s.at(char::is_ascii_digit) => self.number(start, c),
859	            '"' => self.string(),
860	
861	            '=' if self.s.eat_if('=') => SyntaxKind::EqEq,
862	            '!' if self.s.eat_if('=') => SyntaxKind::ExclEq,
863	            '<' if self.s.eat_if('=') => SyntaxKind::LtEq,
864	            '>' if self.s.eat_if('=') => SyntaxKind::GtEq,
865	            '+' if self.s.eat_if('=') => SyntaxKind::PlusEq,
866	            '-' | '\u{2212}' if self.s.eat_if('=') => SyntaxKind::HyphEq,
867	            '*' if self.s.eat_if('=') => SyntaxKind::StarEq,
868	            '/' if self.s.eat_if('=') => SyntaxKind::SlashEq,
869	            '.' if self.s.eat_if('.') => SyntaxKind::Dots,
870	            '=' if self.s.eat_if('>') => SyntaxKind::Arrow,
871	
872	            '{' => SyntaxKind::LeftBrace,
873	            '}' => SyntaxKind::RightBrace,
874	            '[' => SyntaxKind::LeftBracket,
875	            ']' => SyntaxKind::RightBracket,
876	            '(' => SyntaxKind::LeftParen,
877	            ')' => SyntaxKind::RightParen,
878	            '$' => SyntaxKind::Dollar,
879	            ',' => SyntaxKind::Comma,
880	            ';' => SyntaxKind::Semicolon,
881	            ':' => SyntaxKind::Colon,
882	            '.' => SyntaxKind::Dot,
883	            '+' => SyntaxKind::Plus,
884	            '-' | '\u{2212}' => SyntaxKind::Minus,
885	            '*' => SyntaxKind::Star,
886	            '/' => SyntaxKind::Slash,
887	            '=' => SyntaxKind::Eq,
888	            '<' => SyntaxKind::Lt,
889	            '>' => SyntaxKind::Gt,
890	
891	            c if is_id_start(c) => self.ident(start),
892	
893	            c => self.invalid_char_in_code(c),
894	        }
895	    }
896	
897	    /// Error for an invalid character in code, but try to give good hints for
898	    /// commonly confusing operators.
899	    fn invalid_char_in_code(&mut self, c: char) -> SyntaxKind {
900	        let invalid_char = || eco_format!("the character `{c}` is not valid in code");
901	        let invalid_str = |s: &str| eco_format!("`{s}` is not valid in code");
902	        match c {
903	            // Give a custom hint if we immediately follow a hash.
904	            _ if self.s.scout(-2) == Some('#') => {
905	                self.error(invalid_char());
906	                // This is only an accurate hint if we just came from markup or
907	                // math, but `#!` or `##` in code should be rare enough that
908	                // it's fine (and the first hash will produce its own error).
909	                self.hint("the preceding hash is causing this to parse in code mode");
910	                self.hint("try escaping the preceding hash: `\\#`");
911	                // The span for these hints isn't great, but it's hard to fix.
912	            }
913	            '#' => {
914	                self.error(invalid_char());
915	                self.hint("you are already in code mode");
916	                self.hint("try removing the `#`");
917	            }
918	            '&' if self.s.eat_if('&') => {
919	                self.error(invalid_str("&&"));
920	                self.hint("in Typst, `and` is used for logical AND");
921	            }
922	            '|' if self.s.eat_if('|') => {
923	                self.error(invalid_str("||"));
924	                self.hint("in Typst, `or` is used for logical OR");
925	            }
926	            '!' => {
927	                self.error(invalid_char());
928	                self.hint("in Typst, `not` is used for negation");
929	                self.hint("or did you mean to write `!=` for not-equal?");
930	            }
931	            '~' if self.s.eat_if('=') => {
932	                self.error(invalid_str("~="));
933	                self.hint("in Typst, `!=` is used for not-equal");
934	            }
935	            _ => {
936	                self.error(invalid_char());
937	            }
938	        }
939	        SyntaxKind::Error
940	    }
941	
942	    fn ident(&mut self, start: usize) -> SyntaxKind {
943	        self.s.eat_while(is_id_continue);
944	        let ident = self.s.from(start);
945	
946	        let prev = self.s.get(0..start);
947	        if (!prev.ends_with(['.', '@']) || prev.ends_with(".."))
948	            && let Some(keyword) = keyword(ident)
949	        {
950	            return keyword;
951	        }
952	
953	        if ident == "_" { SyntaxKind::Underscore } else { SyntaxKind::Ident }
954	    }
955	
956	    /// Lex a single number, either an integer or a float, possibly with a
957	    /// numeric suffix (`pt`, `deg`, `%`, etc.). Integers may also have a prefix
958	    /// for binary, octal, or hexadecimal bases, but only base-10 integers can
959	    /// have a numeric suffix (if so, they will be treated as floats in the
960	    /// AST).
961	    ///
962	    /// Floating point numbers can use exponent notation with `e` or `E`, such
963	    /// as `5.0e-3in` for `0.005in`.
964	    fn number(&mut self, start: usize, first_c: char) -> SyntaxKind {
965	        // Handle alternative integer bases.
966	        let base = match first_c {
967	            '0' if self.s.eat_if('x') => Some(NonDecimalBase::Hex),
968	            '0' if self.s.eat_if('o') => Some(NonDecimalBase::Octal),
969	            '0' if self.s.eat_if('b') => Some(NonDecimalBase::Binary),
970	            _ => None,
971	        };
972	
973	        // Read the initial digits.
974	        if base == Some(NonDecimalBase::Hex) {
975	            self.s.eat_while(char::is_ascii_alphanumeric);
976	        } else {
977	            self.s.eat_while(char::is_ascii_digit);
978	        }
979	
980	        // Read floating point digits and exponents.
981	        let mut is_float = false;
982	        if base.is_none() {
983	            // Read digits following a dot. Make sure not to confuse a spread
984	            // operator or a method call for the decimal separator.
985	            if first_c == '.' {
986	                is_float = true; // We already ate the trailing digits above.
987	            } else if !self.s.at("..")
988	                && !self.s.scout(1).is_some_and(is_id_start)
989	                && self.s.eat_if('.')
990	            {
991	                is_float = true;
992	                self.s.eat_while(char::is_ascii_digit);
993	            }
994	
995	            // Read the exponent.
996	            if !self.s.at("em") && self.s.eat_if(['e', 'E']) {
997	                is_float = true;
998	                self.s.eat_if(['+', '-']);
999	                self.s.eat_while(char::is_ascii_digit);
1000	            }
1001	        }
1002	
1003	        let number = self.s.from(start);
1004	        let suffix = self.s.eat_while(|c: char| c.is_ascii_alphanumeric() || c == '%');
1005	
1006	        let mut suffix_result = match suffix {
1007	            "" => Ok(None),
1008	            "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "em" | "fr" | "%" => Ok(Some(())),
1009	            _ => Err(eco_format!("invalid number suffix: `{suffix}`")),
1010	        };
1011	
1012	        let number_result = if is_float {
1013	            if number.parse::<f64>().is_err() {
1014	                // The only invalid case should be when a float lacks digits after
1015	                // the exponent: e.g. `1.2e`, `2.3E-`, or `1EM`.
1016	                Err(eco_format!("invalid floating point number: `{number}`"))
1017	            } else {
1018	                Ok(())
1019	            }
1020	        } else if let Some(non_decimal) = base {
1021	            let name = non_decimal.name();
1022	            // The index `[2..]` skips the leading `0b`/`0o`/`0x`.
1023	            match i64::from_str_radix(&number[2..], non_decimal as u32) {
1024	                Ok(_) if suffix.is_empty() => Ok(()),
1025	                Ok(value) => {
1026	                    if suffix_result.is_ok() {
1027	                        suffix_result = Err(eco_format!(
1028	                            "try using a decimal number: `{value}{suffix}`"
1029	                        ));
1030	                    }
1031	                    Err(eco_format!("{name} numbers cannot have a suffix"))
1032	                }
1033	                Err(e) if *e.kind() == IntErrorKind::Empty => Err(eco_format!(
1034	                    "expected a{} {name} number",
1035	                    if non_decimal == NonDecimalBase::Octal { "n" } else { "" },
1036	                )),
1037	                Err(_) if suffix_result.is_err() => {
1038	                    // We're already erroring, tell them about the invalid
1039	                    // integer first.
1040	                    Err(eco_format!("invalid {name} number: `{number}`"))
1041	                }
1042	                // Invalid digits and positive overflow errors are handled in
1043	                // the AST.
1044	                Err(_) => Ok(()),
1045	            }
1046	        } else {
1047	            // Decimal integer errors are handled in the AST. Note that
1048	            // too-large decimal integers that have suffixes will be silently
1049	            // treated as floats.
1050	            Ok(())
1051	        };
1052	
1053	        // Return our number or write an error with helpful hints.
1054	        match (number_result, suffix_result) {
1055	            // Valid numbers :D
1056	            (Ok(()), Ok(None)) if is_float => SyntaxKind::Float,
1057	            (Ok(()), Ok(None)) => SyntaxKind::Int,
1058	            (Ok(()), Ok(Some(()))) => SyntaxKind::Numeric,
1059	            // Invalid numbers :(
1060	            (Err(number_err), Err(suffix_err)) => {
1061	                let error = self.error(number_err);
1062	                self.hint(suffix_err);
1063	                error
1064	            }
1065	            (Ok(()), Err(msg)) | (Err(msg), Ok(_)) => self.error(msg),
1066	        }
1067	    }
1068	
1069	    fn string(&mut self) -> SyntaxKind {
1070	        let mut escaped = false;
1071	        self.s.eat_until(|c| {
1072	            let stop = c == '"' && !escaped;
1073	            escaped = c == '\\' && !escaped;
1074	            stop
1075	        });
1076	
1077	        if !self.s.eat_if('"') {
1078	            return self.error("unclosed string");
1079	        }
1080	
1081	        SyntaxKind::Str
1082	    }
1083	}
1084	
1085	/// Try to parse an identifier into a keyword.
1086	fn keyword(ident: &str) -> Option<SyntaxKind> {
1087	    Some(match ident {
1088	        "none" => SyntaxKind::None,
1089	        "auto" => SyntaxKind::Auto,
1090	        "true" => SyntaxKind::Bool,
1091	        "false" => SyntaxKind::Bool,
1092	        "not" => SyntaxKind::Not,
1093	        "and" => SyntaxKind::And,
1094	        "or" => SyntaxKind::Or,
1095	        "let" => SyntaxKind::Let,
1096	        "set" => SyntaxKind::Set,
1097	        "show" => SyntaxKind::Show,
1098	        "context" => SyntaxKind::Context,
1099	        "if" => SyntaxKind::If,
1100	        "else" => SyntaxKind::Else,
1101	        "for" => SyntaxKind::For,
1102	        "in" => SyntaxKind::In,
1103	        "while" => SyntaxKind::While,
1104	        "break" => SyntaxKind::Break,
1105	        "continue" => SyntaxKind::Continue,
